// A .d.ts-less CJS package whose shipped JS does NOT typecheck under the
// program's tsconfig (checkJs would flag the string/number comparison and
// the bare Array generic) — the shape maxNodeModuleJsDepth admits into the
// checker's program whenever ANY --npm-static opt-in is active, even
// though THIS package was never opted in. Its checker errors must never
// gate the build: the package's execution home is the island.
'use strict';

/** @type {Array} */
const bag = [];

/** @type {number} */
const VERSION = 'one'; // a checkJs type error, deliberately
void VERSION;

function pick(v) {
  if (v < 'x') return 'low';
  return 'high';
}

module.exports = function label(n) {
  bag.push(n);
  return 'typegapped:' + pick(n) + ':' + bag.length;
};
